{
  "research": [
    {
      "id": "R1",
      "title": "Visual Baselines for Surface Defect Classification",
      "bullets": [
        "Prepared surface inspection images by checking defect labels, standardizing crop dimensions, and separating related samples across training and evaluation splits.",
        "Implemented a prescribed histogram of oriented gradients baseline with a support vector classifier, reviewing misclassifications under uneven illumination and textured backgrounds."
      ]
    },
    {
      "id": "R2",
      "title": "Color-Based Baselines for Scene Image Retrieval",
      "bullets": [
        "Organized scene images into reference and query sets, checked category annotations, and removed duplicate files before baseline evaluation.",
        "Implemented normalized color histograms and nearest neighbor retrieval following an existing protocol, inspecting retrieved examples for confusion between visually similar scene categories."
      ]
    }
  ],
  "publications": [],
  "work": [
    {
      "id": "W1",
      "title": "Routine Operations and Supply Coordination",
      "bullets": [
        "Maintained supply inventories, checked incoming deliveries against order records, and routed missing item reports to the responsible staff.",
        "Organized routine paperwork, updated shared schedules, and tracked outstanding service requests to support daily office operations and shift handoffs."
      ]
    }
  ],
  "projects": [
    {
      "id": "T1",
      "title": "Color Clustering for Image Segmentation",
      "bullets": [
        "Implemented a baseline image segmentation pipeline using color normalization and k-means clustering, converting cluster assignments into pixelwise region maps.",
        "Compared segmentations with reference masks and inspected boundary errors, documenting sensitivity to cluster initialization and foreground objects with similar background colors."
      ]
    },
    {
      "id": "T2",
      "title": "Dimensionality Reduction for Handwritten Digit Classification",
      "bullets": [
        "Implemented a handwritten digit classification baseline using flattened grayscale images, principal component analysis, and logistic regression within a fixed evaluation split.",
        "Compared predictions with and without dimensionality reduction, examining confusion matrices and misclassified images to characterize errors involving ambiguous strokes."
      ]
    }
  ]
}
